package ru.neverland.mintcontracts.procurement;

import java.io.*;
import java.nio.file.*;
import java.sql.*;
import java.util.*;
import java.util.concurrent.*;
import ru.neverland.core.*;

/** Bounded single writer; intent ACK precedes every external debit, refund and legacy publication. */
public final class ProcurementRepository {
    @FunctionalInterface private interface Sql<T>{T run()throws Exception;}
    private final Path path;private final ThreadPoolExecutor worker;private final CompletableFuture<Void> ready,closed=new CompletableFuture<>();private Connection db;private volatile boolean closing,fault,initialized;
    public ProcurementRepository(Path path){this.path=path.toAbsolutePath();worker=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(128),r->{var t=new Thread(r,"NeverLand-procurement-ledger");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy()){@Override protected void terminated(){Throwable failure=null;try{if(db!=null&&initialized)try(var s=db.createStatement();var rows=s.executeQuery("PRAGMA wal_checkpoint(TRUNCATE)")){if(!rows.next()||rows.getInt(1)!=0||rows.getInt(2)!=0||rows.getInt(3)!=0)throw new IOException("Закупки не подтвердили закрытие WAL");}}catch(Throwable error){failure=error;}finally{try{if(db!=null)db.close();}catch(Throwable error){if(failure==null)failure=error;else failure.addSuppressed(error);}}if(failure==null)closed.complete(null);else closed.completeExceptionally(failure);}};ready=this.<Void>submit(()->{open();initialized=true;return null;}).toCompletableFuture();}
    public CompletionStage<Void> ready(){return ready;}public boolean available(){return ready.isDone()&&!ready.isCompletedExceptionally()&&!fault&&!closing;}public synchronized CompletionStage<Void> closeAsync(){closing=true;worker.shutdown();return closed;}
    private <T>CompletionStage<T> submit(Sql<T> work){var result=new CompletableFuture<T>();if(closing)return CompletableFuture.failedFuture(new IOException("Закупки останавливаются"));try{worker.execute(()->{try{if(SuiteState.held())throw new IllegalStateException("Procurement SQL under SuiteState");if(fault)throw new IOException("Журнал закупок требует проверки");result.complete(work.run());}catch(Throwable error){if(error instanceof SQLException||error instanceof IOException)fault=true;result.completeExceptionally(error);}});}catch(RejectedExecutionException full){result.completeExceptionally(new IllegalStateException("Очередь закупок заполнена; повторите позже"));}return result;}
    private void open()throws Exception{Files.createDirectories(path.getParent());Class.forName("org.sqlite.JDBC");db=DriverManager.getConnection("jdbc:sqlite:"+path);try(var s=db.createStatement()){s.execute("PRAGMA busy_timeout=1000");s.execute("PRAGMA foreign_keys=ON");try(var r=s.executeQuery("PRAGMA journal_mode=WAL")){if(!r.next()||!r.getString(1).equalsIgnoreCase("wal"))throw new IOException("Закупкам нужен SQLite WAL");}s.execute("PRAGMA synchronous=FULL");try(var r=s.executeQuery("PRAGMA user_version")){if(!r.next()||r.getInt(1)>1)throw new IOException("Неизвестная версия закупок");}try(var r=s.executeQuery("PRAGMA quick_check")){if(!r.next()||!r.getString(1).equals("ok"))throw new IOException("Повреждена база закупок");}
        s.execute("CREATE TABLE IF NOT EXISTS requests(id TEXT PRIMARY KEY,town TEXT NOT NULL,town_name TEXT NOT NULL,actor TEXT NOT NULL,actor_name TEXT NOT NULL,project TEXT NOT NULL,level INTEGER NOT NULL,building TEXT NOT NULL,fingerprint TEXT NOT NULL,item_key TEXT NOT NULL,item TEXT NOT NULL,name TEXT NOT NULL,amount INTEGER NOT NULL,cents INTEGER NOT NULL,duration INTEGER NOT NULL,created INTEGER NOT NULL,expires INTEGER NOT NULL,state TEXT NOT NULL,started INTEGER NOT NULL,detail TEXT NOT NULL,refund_actor TEXT NOT NULL,refund_name TEXT NOT NULL,refund_reason TEXT NOT NULL)");
        s.execute("CREATE INDEX IF NOT EXISTS request_city ON requests(town,created)");s.execute("CREATE INDEX IF NOT EXISTS request_pending ON requests(state,created)");s.execute("CREATE INDEX IF NOT EXISTS request_item ON requests(town,project,item_key)");s.execute("CREATE TABLE IF NOT EXISTS history(id TEXT PRIMARY KEY,request TEXT NOT NULL REFERENCES requests(id),town TEXT NOT NULL,town_name TEXT NOT NULL,actor TEXT NOT NULL,actor_name TEXT NOT NULL,kind TEXT NOT NULL,detail TEXT NOT NULL,at INTEGER NOT NULL)");s.execute("CREATE TABLE IF NOT EXISTS audit_ack(id TEXT PRIMARY KEY REFERENCES history(id))");s.execute("PRAGMA user_version=1");}}
    private <T>T tx(Sql<T> work)throws Exception{db.setAutoCommit(false);try{T result=work.run();db.commit();return result;}catch(Throwable error){try{db.rollback();}catch(SQLException other){error.addSuppressed(other);}throw error;}finally{db.setAutoCommit(true);}}
    private void exec(String sql,Object...args)throws SQLException{try(var s=db.prepareStatement(sql)){for(int i=0;i<args.length;i++)s.setObject(i+1,args[i]);s.executeUpdate();}}
    private long count(String sql,Object...args)throws SQLException{try(var s=db.prepareStatement(sql)){for(int i=0;i<args.length;i++)s.setObject(i+1,args[i]);try(var r=s.executeQuery()){return r.next()?r.getLong(1):0;}}}
    private ProcurementOrder read(UUID id)throws Exception{try(var s=db.prepareStatement("SELECT * FROM requests WHERE id=?")){s.setString(1,id.toString());try(var r=s.executeQuery()){if(!r.next())return null;String refund=r.getString("refund_actor");try{return new ProcurementOrder(id,UUID.fromString(r.getString("town")),r.getString("town_name"),UUID.fromString(r.getString("actor")),r.getString("actor_name"),r.getString("project"),r.getInt("level"),r.getString("building"),r.getString("fingerprint"),r.getString("item_key"),r.getString("item"),r.getString("name"),r.getInt("amount"),r.getLong("cents"),r.getLong("duration"),r.getLong("created"),r.getLong("expires"),r.getString("state"),r.getLong("started"),r.getString("detail"),refund.isEmpty()?null:UUID.fromString(refund),r.getString("refund_name"),r.getString("refund_reason"));}catch(RuntimeException invalid){throw new IOException("Повреждена сохранённая смета "+id,invalid);}}}}
    private ProcurementOrder require(UUID id)throws Exception{var row=read(id);if(row==null)throw new IllegalArgumentException("Смета закупки не найдена");return row;}
    private void write(ProcurementOrder r)throws SQLException{exec("INSERT INTO requests VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET state=excluded.state,started=excluded.started,detail=excluded.detail,refund_actor=excluded.refund_actor,refund_name=excluded.refund_name,refund_reason=excluded.refund_reason",r.id().toString(),r.town().toString(),r.townName(),r.actor().toString(),r.actorName(),r.project(),r.level(),r.building(),r.fingerprint(),r.itemKey(),r.item(),r.name(),r.amount(),r.cents(),r.duration(),r.created(),r.expires(),r.state(),r.started(),r.detail(),r.refundActor()==null?"":r.refundActor().toString(),r.refundName(),r.refundReason());}
    private void history(ProcurementOrder r,String kind,UUID actor,String name,String detail)throws SQLException{String id=AuditRecord.id("NeverLandTownyContracts",r.id().toString(),"procurement:"+kind);exec("INSERT OR IGNORE INTO history VALUES(?,?,?,?,?,?,?,?,?)",id,r.id().toString(),r.town().toString(),r.townName(),actor.toString(),name,kind,detail,System.currentTimeMillis());}
    public CompletionStage<ProcurementOrder> get(UUID id){return submit(()->require(id));}
    public CompletionStage<ProcurementOrder> quote(ProcurementOrder row){return submit(()->tx(()->{if(!row.state().equals("QUOTE")||row.started()!=0||row.refundActor()!=null)throw new IllegalArgumentException("Новая смета не может содержать оплату или возврат");var old=read(row.id());if(old!=null){if(!old.equals(row))throw new IllegalArgumentException("ID занят другой сметой");return old;}long now=System.currentTimeMillis();if(count("SELECT COUNT(*) FROM requests")>=100_000)throw new IllegalArgumentException("Журнал закупок заполнен; нужна проверенная архивация администратора");if(count("SELECT COUNT(*) FROM requests WHERE state='QUOTE' AND expires>? AND actor=?",now,row.actor().toString())>=16||count("SELECT COUNT(*) FROM requests WHERE state='QUOTE' AND expires>? AND town=?",now,row.town().toString())>=64||count("SELECT COUNT(*) FROM requests WHERE state='QUOTE' AND expires>?",now)>=2048)throw new IllegalArgumentException("Слишком много открытых смет; дождитесь окончания прежних подтверждений");write(row);return row;}));}
    public CompletionStage<ProcurementOrder> funding(UUID id){return submit(()->tx(()->{var r=require(id);if(!r.state().equals("QUOTE"))return r;if(r.expires()<System.currentTimeMillis())throw new IllegalArgumentException("Смета устарела; откройте новый расчёт");if(count("SELECT COUNT(*) FROM requests WHERE town=? AND project=? AND level=? AND item_key=? AND state IN ('FUNDING','FUNDED','PUBLISHING','REVIEW','REFUNDING')",r.town().toString(),r.project(),r.level(),r.itemKey())>0)throw new IllegalArgumentException("Этот материал уже ожидает оплаты или публикации");if(count("SELECT COUNT(*) FROM requests WHERE town=? AND state IN ('FUNDING','FUNDED','PUBLISHING','REVIEW','REFUNDING')",r.town().toString())>=8||count("SELECT COUNT(*) FROM requests WHERE state IN ('FUNDING','FUNDED','PUBLISHING','REVIEW','REFUNDING')")>=256)throw new IllegalArgumentException("Слишком много незавершённых расчётов");var next=r.state("FUNDING",0,"Казна подтверждает резерв награды");write(next);history(next,"FUNDING",r.actor(),r.actorName(),"Заморожена смета; награда "+r.cents()+" коп.");return next;}));}
    public static String validateBank(ProcurementOrder r,Map<String,Object> proof,boolean refund){String status=String.valueOf(proof.get("status"));if(status.equals("ABSENT"))return status;String operation=(refund?r.refundId():r.id()).toString(),actor=(refund?r.refundActor():r.actor()).toString(),reason=refund?r.refundReason():r.bankReason();long cents=-1;try{cents=new java.math.BigDecimal(String.valueOf(proof.get("cents"))).longValueExact();}catch(RuntimeException ignored){}
        if(!operation.equals(String.valueOf(proof.get("operation")))||!r.town().toString().equals(String.valueOf(proof.get("town")))||!"infrastructure".equals(proof.get("category"))||!"contracts".equals(proof.get("source"))||cents!=r.cents()||!reason.equals(proof.get("reason"))||!actor.equals(String.valueOf(proof.get("actor")))||!"NeverLandTownyContracts".equals(proof.get("owner")))throw new IllegalArgumentException("Банковская квитанция не совпадает со сметой; заказ не опубликован");
        if(refund&&(!"REFUND".equals(proof.get("kind"))||!r.id().toString().equals(String.valueOf(proof.get("backingDebit")))))throw new IllegalArgumentException("Возврат не относится к исходному резерву");if(!refund&&status.equals("PAID")&&!Boolean.TRUE.equals(proof.get("backingAvailable")))throw new IllegalArgumentException("Резерв уже возвращается или недоступен; публикация запрещена");if(!refund&&proof.containsKey("kind")&&!"DEBIT".equals(proof.get("kind")))throw new IllegalArgumentException("Ожидалась квитанция резерва");if(!Set.of("PREPARED","INVOKING","PAID","REJECTED","REVIEW").contains(status))throw new IllegalArgumentException("Неизвестный статус банка");return status;
    }
    public CompletionStage<ProcurementOrder> bank(UUID id,Map<String,Object> proof,boolean refund){var frozen=Map.copyOf(proof);return submit(()->tx(()->{var r=require(id);String status=validateBank(r,frozen,refund);if(refund){if(!r.state().equals("REFUNDING")){if(r.state().equals("REFUNDED")&&status.equals("PAID"))return r;throw new IllegalArgumentException("Возврат уже закрыт или не подготовлен");}if(status.equals("PAID")){var next=r.state("REFUNDED",r.started(),"Весь неопубликованный резерв возвращён городу");write(next);history(next,"REFUNDED",r.refundActor(),r.refundName(),next.detail());return next;}if(Set.of("REJECTED","REVIEW").contains(status)){var next=r.state("REFUNDING",r.started(),status.equals("REJECTED")?"Казна отклонила возврат; резерв сохранён, требуется сверка администратора":"Результат возврата требует сверки администратора; повторного зачисления нет");write(next);history(next,"REFUND_"+status,r.refundActor(),r.refundName(),next.detail());return next;}return r;}
        if(!Set.of("FUNDING","REVIEW").contains(r.state()))return r;if(status.equals("ABSENT")||status.equals("PREPARED")||status.equals("INVOKING"))return r;String nextState=status.equals("PAID")?"FUNDED":status;String detail=switch(nextState){case "FUNDED"->"Награда оплачена; мэр может опубликовать заказ или вернуть резерв";case "REJECTED"->"Банк отклонил списание; заказ не опубликован";default->"Результат списания требует сверки администратора; повторного списания нет";};var next=r.state(nextState,r.started(),detail);write(next);history(next,nextState,r.actor(),r.actorName(),detail);return next;}));}
    public CompletionStage<ProcurementOrder> publishing(UUID id){return submit(()->tx(()->{var r=require(id);if(r.state().equals("PUBLISHING")||r.state().equals("PUBLISHED")||r.state().equals("SETTLED"))return r;if(!r.state().equals("FUNDED"))throw new IllegalArgumentException("Сначала нужно подтверждение оплаты");var next=r.state("PUBLISHING",System.currentTimeMillis(),"Оплата подтверждена; публикация ожидает квитанции контракта");write(next);history(next,"PUBLISHING",r.actor(),r.actorName(),next.detail());return next;}));}
    public CompletionStage<ProcurementOrder> published(UUID id,UUID actor,String name,boolean settled){return submit(()->tx(()->{var r=require(id);if(r.state().equals("SETTLED")||r.state().equals("PUBLISHED")&&!settled)return r;if(!Set.of("PUBLISHING","PUBLISHED").contains(r.state()))throw new IllegalArgumentException("Публикация не подготовлена");var next=r.state(settled?"SETTLED":"PUBLISHED",r.started(),settled?"Городской контракт уже закрыт; его выплаты сохранены отдельно":"Заказ опубликован в /t contracts; ресурсы поступят на общий склад города");write(next);history(next,next.state(),actor,name,next.detail());return next;}));}
    public CompletionStage<ProcurementOrder> cancel(UUID id,UUID actor,String name,boolean confirmedUnpublished){return submit(()->tx(()->{var r=require(id);if(Set.of("CANCELLED","REFUNDED","REFUNDING").contains(r.state()))return r;if(r.state().equals("QUOTE")){var next=r.state("CANCELLED",0,"Смета отменена до оплаты");write(next);history(next,"CANCELLED",actor,name,next.detail());return next;}if(!(r.state().equals("FUNDED")||r.state().equals("PUBLISHING")&&confirmedUnpublished))throw new IllegalArgumentException("Дождитесь сверки оплаты или используйте отмену опубликованного городского контракта");var next=r.refund(actor,name,"Отмена неопубликованной закупки "+r.id());write(next);history(next,"REFUNDING",actor,name,next.detail());return next;}));}
    public CompletionStage<List<ProcurementOrder>> requests(UUID town,int page){return submit(()->{if(page<1||page>5000)throw new IllegalArgumentException("Неверная страница закупок");var rows=new ArrayList<ProcurementOrder>();try(var s=db.prepareStatement("SELECT id FROM requests WHERE town=? ORDER BY created DESC,id LIMIT 20 OFFSET ?")){s.setString(1,town.toString());s.setLong(2,(page-1L)*20);try(var r=s.executeQuery()){while(r.next())rows.add(require(UUID.fromString(r.getString(1))));}}return List.copyOf(rows);});}
    public CompletionStage<List<ProcurementOrder>> outstanding(UUID town,String project,Set<UUID> active){var frozen=Set.copyOf(active);if(frozen.size()>45)throw new IllegalArgumentException("Слишком много действующих контрактов");return submit(()->{var rows=new ArrayList<ProcurementOrder>();String membership=frozen.isEmpty()?"0":"id IN ("+String.join(",",Collections.nCopies(frozen.size(),"?"))+")";try(var s=db.prepareStatement("SELECT id FROM requests WHERE town=? AND project=? AND (state IN ('FUNDING','FUNDED','PUBLISHING','REVIEW','REFUNDING') OR "+membership+") ORDER BY created LIMIT 64")){s.setString(1,town.toString());s.setString(2,project);int i=3;for(UUID id:frozen)s.setString(i++,id.toString());try(var r=s.executeQuery()){while(r.next())rows.add(require(UUID.fromString(r.getString(1))));}}return List.copyOf(rows);});}
    public CompletionStage<List<AuditRecord>> auditPending(){return submit(()->{var rows=new ArrayList<AuditRecord>();try(var s=db.createStatement();var r=s.executeQuery("SELECT h.*,q.cents FROM history h JOIN requests q ON q.id=h.request LEFT JOIN audit_ack a ON a.id=h.id WHERE a.id IS NULL ORDER BY h.at,h.id LIMIT 64")){while(r.next()){var town=new AuditRecord.Party("TOWN",r.getString("town"),r.getString("town_name"),r.getString("town"));var actor=new AuditRecord.Party("PLAYER",r.getString("actor"),r.getString("actor_name"),r.getString("town"));var escrow=new AuditRecord.Party("ESCROW",r.getString("request"),"Резерв закупки",r.getString("town"));boolean refund=r.getString("kind").startsWith("REFUND");rows.add(new AuditRecord(r.getString("id"),r.getLong("at"),"NeverLandTownyContracts","CONTRACT_PAYMENT","PROCUREMENT_"+r.getString("kind"),r.getString("request"),actor,refund?escrow:town,refund?town:escrow,"",0,AuditTrail.cents(r.getLong("cents")),r.getString("detail")));}}return List.copyOf(rows);});}
    public CompletionStage<Void> auditAcknowledged(List<String> ids){var frozen=List.copyOf(ids);if(frozen.size()>64)throw new IllegalArgumentException("Большая пачка аудита");return submit(()->tx(()->{for(String id:frozen)exec("INSERT OR IGNORE INTO audit_ack VALUES(?)",id);return null;}));}
}
